9	async function writeAuditLog(
10	  adminId: string,
11	  action: string,
12	  targetType: string,
13	  targetId: string,
14	  metadata: Record<string, unknown> = {}
15	) {
16	  const { error } = await supabase.from("audit_logs").insert({
17	    admin_id: adminId,
18	    action,
19	    target_type: targetType,
20	    target_id: targetId,
21	    metadata,
22	  });
