30	
31	interface ChangePlanArgs {
32	  userId: string;
33	  plan: PlanType;
34	  previousPlan?: PlanType;
35	}
36	
37	export function useChangePlan() {
38	  const queryClient = useQueryClient();
39	  const { user } = useAuth();
40	
41	  return useMutation({
42	    mutationFn: async ({ userId, plan, previousPlan }: ChangePlanArgs) => {
43	      if (!user) throw new Error("Not authenticated");
44	
45	      const newLimit =
46	        plan === "agency" ? 500 : plan === "pro" ? 25 : 3;
47	
48	      const { error } = await supabase
49	        .from("profiles")
50	        .update({ plan, scan_limit: newLimit })
51	        .eq("id", userId);
52	
53	      if (error) throw new Error(error.message);
54	
55	      await writeAuditLog(user.id, "change_plan", "profile", userId, {
56	        previous_plan: previousPlan,
57	        new_plan: plan,
58	      });
59	    },
60	    onSuccess: (_, { userId }) => {
61	      toast.success("Plan updated successfully");
62	      queryClient.invalidateQueries({ queryKey: ["admin", "users"] });
63	      queryClient.invalidateQueries({ queryKey: ["admin", "user", userId] });
64	      queryClient.invalidateQueries({ queryKey: ["admin", "stats"] });
65	    },
66	    onError: (error: Error) => {
67	      toast.error(`Failed to update plan: ${error.message}`);
68	    },
69	  });
70	}
