1	import { useQuery } from "@tanstack/react-query";
2	import supabase from "@/lib/supabase";
3	
4	export interface AdminStats {
5	  totalUsers: number;
6	  totalScans: number;
7	  activeUsers: number; // scanned in last 7 days
8	  failedScans: number;
9	}
10	
11	async function fetchAdminStats(): Promise<AdminStats> {
12	  const sevenDaysAgo = new Date(
13	    Date.now() - 7 * 24 * 60 * 60 * 1000
14	  ).toISOString();
15	
16	  const [
17	    { count: totalUsers, error: usersError },
18	    { count: totalScans, error: scansError },
19	    { count: failedScans, error: failedError },
20	    { data: activeData, error: activeError },
21	  ] = await Promise.all([
22	    supabase
23	      .from("profiles")
24	      .select("*", { count: "exact", head: true }),
25	    supabase
26	      .from("scans")
27	      .select("*", { count: "exact", head: true }),
28	    supabase
29	      .from("scans")
30	      .select("*", { count: "exact", head: true })
31	      .eq("status", "failed"),
32	    supabase
33	      .from("scans")
34	      .select("user_id")
35	      .gte("created_at", sevenDaysAgo),
36	  ]);
37	
38	  if (usersError) throw new Error(usersError.message);
39	  if (scansError) throw new Error(scansError.message);
40	  if (failedError) throw new Error(failedError.message);
41	  if (activeError) throw new Error(activeError.message);
42	
43	  const uniqueActiveUsers = new Set((activeData ?? []).map((r) => r.user_id))
44	    .size;
45	
46	  return {
47	    totalUsers: totalUsers ?? 0,
48	    totalScans: totalScans ?? 0,
49	    activeUsers: uniqueActiveUsers,
50	    failedScans: failedScans ?? 0,
51	  };
52	}
53	
54	export function useAdminStats() {
55	  return useQuery({
56	    queryKey: ["admin", "stats"],
57	    queryFn: fetchAdminStats,
58	    staleTime: 60_000, // 1 minute
59	  });
60	}
