1	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
2	import supabase from "@/lib/supabase";
3	import { toast } from "sonner";
4	
5	// ── Types ─────────────────────────────────────────────────────
6	
7	export interface SystemStats {
8	  profilesCount: number;
9	  scansCount: number;
10	  scanResultsCount: number;
11	  screenshotsCount: number;
12	  supabaseConnected: boolean;
13	}
14	
15	// ── Fetch helpers ─────────────────────────────────────────────
16	
17	async function fetchSystemStats(): Promise<SystemStats> {
18	  const [
19	    { count: profilesCount, error: profilesError },
20	    { count: scansCount, error: scansError },
21	    { count: scanResultsCount, error: resultsError },
22	    { count: screenshotsCount, error: screenshotsError },
23	  ] = await Promise.all([
24	    supabase.from("profiles").select("*", { count: "exact", head: true }),
25	    supabase.from("scans").select("*", { count: "exact", head: true }),
26	    supabase.from("scan_results").select("*", { count: "exact", head: true }),
27	    supabase
28	      .from("scans")
29	      .select("*", { count: "exact", head: true })
30	      .not("screenshot_url", "is", null),
31	  ]);
32	
33	  // If any query succeeded, Supabase is connected. Errors indicate permission issues, not connectivity.
34	  const supabaseConnected = !profilesError || profilesError.code !== "PGRST301";
35	
36	  return {
37	    profilesCount: profilesCount ?? 0,
38	    scansCount: scansCount ?? 0,
39	    scanResultsCount: scanResultsCount ?? 0,
40	    screenshotsCount: screenshotsCount ?? 0,
41	    supabaseConnected,
42	  };
43	}
