45	// ── Hooks ─────────────────────────────────────────────────────
46	
47	export function useSystemStats() {
48	  return useQuery({
49	    queryKey: ["admin", "system-stats"],
50	    queryFn: fetchSystemStats,
51	    staleTime: 30_000,
52	  });
53	}
