55	export function useResetMonthlyScans() {
56	  const queryClient = useQueryClient();
57	
58	  return useMutation({
59	    mutationFn: async () => {
60	      const { error } = await supabase.rpc("reset_monthly_scans");
61	      if (error) throw new Error(error.message);
62	    },
63	    onSuccess: () => {
64	      toast.success("Monthly scan counters reset for all users");
65	      queryClient.invalidateQueries({ queryKey: ["admin"] });
66	    },
67	    onError: (error: Error) => {
68	      toast.error(`Reset failed: ${error.message}`);
69	    },
70	  });
71	}
72	
73	export function useClearFailedScans() {
74	  const queryClient = useQueryClient();
75	
76	  return useMutation({
77	    mutationFn: async () => {
78	      const thirtyDaysAgo = new Date(
79	        Date.now() - 30 * 24 * 60 * 60 * 1000
80	      ).toISOString();
81	
82	      // Delete scan_results for old failed scans first
83	      const { data: failedScans, error: fetchError } = await supabase
84	        .from("scans")
85	        .select("id")
86	        .eq("status", "failed")
87	        .lte("created_at", thirtyDaysAgo);
88	
89	      if (fetchError) throw new Error(fetchError.message);
90	
91	      const scanIds = (failedScans ?? []).map((s) => s.id);
92	
93	      if (scanIds.length === 0) {
94	        return 0;
95	      }
96	
97	      const { error: resultsError } = await supabase
98	        .from("scan_results")
99	        .delete()
100	        .in("scan_id", scanIds);
101	
102	      if (resultsError) throw new Error(resultsError.message);
103	
104	      const { count, error: deleteError } = await supabase
105	        .from("scans")
106	        .delete({ count: "exact" })
107	        .eq("status", "failed")
108	        .lte("created_at", thirtyDaysAgo);
109	
110	      if (deleteError) throw new Error(deleteError.message);
111	
112	      return count ?? 0;
113	    },
114	    onSuccess: (count) => {
115	      toast.success(
116	        count === 0
117	          ? "No old failed scans to clear"
118	          : `Cleared ${count} failed scan${count === 1 ? "" : "s"}`
119	      );
120	      queryClient.invalidateQueries({ queryKey: ["admin"] });
121	    },
122	    onError: (error: Error) => {
123	      toast.error(`Clear failed: ${error.message}`);
124	    },
125	  });
126	}
