1	import { useQuery } from "@tanstack/react-query";
2	import supabase from "@/lib/supabase";
3	import type { ProfileRow } from "@/types/database";
4	
5	// ── Types ─────────────────────────────────────────────────────
6	
7	export interface AtRiskUser extends ProfileRow {
8	  has_failed_scans: boolean;
9	  never_scanned: boolean;
10	  at_scan_limit: boolean;
11	  last_scan_date: string | null;
12	}
13	
14	export interface SupportStats {
15	  usersAtLimit: number;
16	  usersWithFailedScans: number;
17	  newSignupsLastWeek: number;
18	}
19	
20	// ── Fetch helpers ─────────────────────────────────────────────
21	
22	async function fetchAtRiskUsers(): Promise<AtRiskUser[]> {
23	  const sevenDaysAgo = new Date(
24	    Date.now() - 7 * 24 * 60 * 60 * 1000
25	  ).toISOString();
26	
27	  // Fetch all profiles
28	  const { data: profiles, error: profilesError } = await supabase
29	    .from("profiles")
30	    .select("*")
31	    .order("created_at", { ascending: false })
32	    .limit(200);
33	
34	  if (profilesError) throw new Error(profilesError.message);
35	
36	  // Fetch users with failed scans in last 7 days
37	  const { data: failedScansData, error: failedError } = await supabase
38	    .from("scans")
39	    .select("user_id")
40	    .eq("status", "failed")
41	    .gte("created_at", sevenDaysAgo);
42	
43	  if (failedError) throw new Error(failedError.message);
44	
45	  // Fetch most recent scan per user
46	  const { data: lastScans, error: lastScansError } = await supabase
47	    .from("scans")
48	    .select("user_id, created_at")
49	    .order("created_at", { ascending: false });
50	
51	  if (lastScansError) throw new Error(lastScansError.message);
52	
53	  const failedUserIds = new Set(
54	    (failedScansData ?? []).map((r) => r.user_id)
55	  );
56	
57	  // Build a map of user_id → last scan date
58	  const lastScanMap = new Map<string, string>();
59	  for (const scan of lastScans ?? []) {
60	    if (!lastScanMap.has(scan.user_id)) {
61	      lastScanMap.set(scan.user_id, scan.created_at);
62	    }
63	  }
64	
65	  const atRisk: AtRiskUser[] = [];
66	
67	  for (const profile of profiles ?? []) {
68	    const p = profile as ProfileRow;
69	    const atLimit = p.scans_used >= p.scan_limit;
70	    const hasFailed = failedUserIds.has(p.id);
71	    const neverScanned = !lastScanMap.has(p.id);
72	    const lastScanDate = lastScanMap.get(p.id) ?? null;
73	
74	    if (atLimit || hasFailed || neverScanned) {
75	      atRisk.push({
76	        ...p,
77	        has_failed_scans: hasFailed,
78	        never_scanned: neverScanned,
79	        at_scan_limit: atLimit,
80	        last_scan_date: lastScanDate,
81	      });
82	    }
83	  }
84	
85	  // Sort: at limit first, then failed scans, then never scanned
86	  return atRisk.sort((a, b) => {
87	    const scoreA = (a.at_scan_limit ? 3 : 0) + (a.has_failed_scans ? 2 : 0) + (a.never_scanned ? 1 : 0);
88	    const scoreB = (b.at_scan_limit ? 3 : 0) + (b.has_failed_scans ? 2 : 0) + (b.never_scanned ? 1 : 0);
89	    return scoreB - scoreA;
90	  });
91	}
92	
93	async function fetchSupportStats(): Promise<SupportStats> {
94	  const sevenDaysAgo = new Date(
95	    Date.now() - 7 * 24 * 60 * 60 * 1000
96	  ).toISOString();
97	
98	  const [
99	    { data: profiles, error: profilesError },
100	    { data: failedScans, error: failedError },
101	    { count: newSignups, error: signupsError },
102	  ] = await Promise.all([
103	    supabase.from("profiles").select("scans_used, scan_limit"),
104	    supabase
105	      .from("scans")
106	      .select("user_id")
107	      .eq("status", "failed")
108	      .gte("created_at", sevenDaysAgo),
109	    supabase
110	      .from("profiles")
111	      .select("*", { count: "exact", head: true })
112	      .gte("created_at", sevenDaysAgo),
113	  ]);
114	
115	  if (profilesError) throw new Error(profilesError.message);
116	  if (failedError) throw new Error(failedError.message);
117	  if (signupsError) throw new Error(signupsError.message);
118	
119	  const usersAtLimit = (profiles ?? []).filter(
120	    (p) => p.scans_used >= p.scan_limit
121	  ).length;
122	
123	  const usersWithFailedScans = new Set(
124	    (failedScans ?? []).map((r) => r.user_id)
125	  ).size;
126	
127	  return {
128	    usersAtLimit,
129	    usersWithFailedScans,
130	    newSignupsLastWeek: newSignups ?? 0,
131	  };
132	}
133	
134	// ── Hooks ─────────────────────────────────────────────────────
135	
136	export function useAtRiskUsers() {
137	  return useQuery({
138	    queryKey: ["admin", "at-risk-users"],
139	    queryFn: fetchAtRiskUsers,
140	    staleTime: 60_000,
141	  });
142	}
143	
144	export function useSupportStats() {
145	  return useQuery({
146	    queryKey: ["admin", "support-stats"],
147	    queryFn: fetchSupportStats,
148	    staleTime: 60_000,
149	  });
150	}
151

