/**
 * Feature Flags — stored in Supabase system_config table.
 *
 * Run in Supabase SQL editor to create the table:
 *
 * CREATE TABLE IF NOT EXISTS system_config (
 *   key TEXT PRIMARY KEY,
 *   value JSONB NOT NULL DEFAULT '{}',
 *   updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
 * );
 * ALTER TABLE system_config ENABLE ROW LEVEL SECURITY;
 * CREATE POLICY "Admins can manage system_config" ON system_config
 *   FOR ALL USING (
 *     EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role IN ('admin', 'super_admin'))
 *   );
 */

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import { toast } from "sonner";

export interface FlagDefinition {
  key: string;
  label: string;
  description: string;
  defaultValue: boolean;
  category: "ui" | "feature" | "system";
  requiresSuperAdmin?: boolean;
}

export const FLAG_DEFINITIONS: FlagDefinition[] = [
  {
    key: "agent_hub_enabled",
    label: "AI Agent Hub",
    description: "Show the AI Agent Hub section in the user sidebar navigation.",
    defaultValue: true,
    category: "ui",
  },
  {
    key: "integrations_enabled",
    label: "Integrations Page",
    description:
      "Show the Integrations page (Hotjar, GA4, Clarity, Search Console) in user navigation.",
    defaultValue: true,
    category: "ui",
  },
  {
    key: "pdf_export_enabled",
    label: "PDF Export",
    description:
      "Allow users to download audit reports as PDF. Requires a PDF generation service.",
    defaultValue: false,
    category: "feature",
  },
  {
    key: "email_notifications_enabled",
    label: "Email Notifications",
    description:
      "Send email alerts when scan completes, plan changes, or usage limit is reached.",
    defaultValue: false,
    category: "feature",
  },
  {
    key: "free_scan_enabled",
    label: "Public Scan (No Auth)",
    description:
      "Allow anonymous users to run a scan without signing in. Uses rate limiting.",
    defaultValue: true,
    category: "feature",
  },
  {
    key: "maintenance_mode",
    label: "Maintenance Mode",
    description:
      "Show a maintenance banner to all users. Does not block access — visual notice only.",
    defaultValue: false,
    category: "system",
    requiresSuperAdmin: true,
  },
];

const DEFAULT_FLAGS: Record<string, boolean> = Object.fromEntries(
  FLAG_DEFINITIONS.map((f) => [f.key, f.defaultValue])
);

export interface FeatureFlagsData {
  flags: Record<string, boolean>;
  updatedAt: string | null;
}

async function fetchFeatureFlags(): Promise<FeatureFlagsData> {
  const { data, error } = await supabase
    .from("system_config")
    .select("value, updated_at")
    .eq("key", "feature_flags")
    .single();

  if (error && error.code !== "PGRST116") {
    // PGRST116 = row not found — that's fine, we use defaults
    throw new Error(error.message);
  }

  const stored = (data?.value ?? {}) as Record<string, boolean>;

  // Merge stored values with defaults (stored values take priority)
  const flags: Record<string, boolean> = { ...DEFAULT_FLAGS, ...stored };

  return {
    flags,
    updatedAt: data?.updated_at ?? null,
  };
}

// ── Admin hook: reads + writes ────────────────────────────────

export function useFeatureFlags() {
  return useQuery({
    queryKey: ["admin", "feature-flags"],
    queryFn: fetchFeatureFlags,
    staleTime: 60_000,
  });
}

export function useUpdateFeatureFlag() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({
      key,
      enabled,
      currentFlags,
    }: {
      key: string;
      enabled: boolean;
      currentFlags: Record<string, boolean>;
    }) => {
      const mergedFlags = { ...currentFlags, [key]: enabled };

      const { error } = await supabase.from("system_config").upsert(
        {
          key: "feature_flags",
          value: mergedFlags,
          updated_at: new Date().toISOString(),
        },
        { onConflict: "key" }
      );

      if (error) throw new Error(error.message);

      return { key, enabled, mergedFlags };
    },
    onSuccess: (result) => {
      const flagDef = FLAG_DEFINITIONS.find((f) => f.key === result.key);
      const label = flagDef?.label ?? result.key;
      toast.success(`${label} ${result.enabled ? "enabled" : "disabled"}`);
      // Invalidate both admin and app-level queries
      queryClient.invalidateQueries({ queryKey: ["admin", "feature-flags"] });
      queryClient.invalidateQueries({ queryKey: ["feature-flags"] });
    },
    onError: (error: Error) => {
      toast.error(`Failed to update flag: ${error.message}`);
    },
  });
}

/**
 * Global feature flag hook — used throughout the app (not admin-only).
 * Reads from the same system_config table as the admin feature flags.
 * Has a longer staleTime (5 min) since feature flags change rarely.
 */

import { useQuery } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import { FLAG_DEFINITIONS } from "@/hooks/admin/use-feature-flags";

const DEFAULT_FLAGS: Record<string, boolean> = Object.fromEntries(
  FLAG_DEFINITIONS.map((f) => [f.key, f.defaultValue])
);

async function fetchAllFeatureFlags(): Promise<Record<string, boolean>> {
  const { data, error } = await supabase
    .from("system_config")
    .select("value")
    .eq("key", "feature_flags")
    .single();

  if (error && error.code !== "PGRST116") {
    // On error, return defaults silently — never break app for missing config
    return DEFAULT_FLAGS;
  }

  const stored = (data?.value ?? {}) as Record<string, boolean>;
  return { ...DEFAULT_FLAGS, ...stored };
}

/**
 * Returns the boolean value of a single feature flag.
 * Falls back to `defaultValue` if the flag is not set or loading.
 */
export function useFeatureFlag(key: string, defaultValue = true): boolean {
  const { data } = useQuery({
    queryKey: ["feature-flags"],
    queryFn: fetchAllFeatureFlags,
    staleTime: 5 * 60 * 1000, // 5 minutes
    // Never throw on error — silently use defaults
    retry: 1,
  });

  if (data === undefined) {
    // Still loading — return the flag's defined default or the passed default
    const flagDef = FLAG_DEFINITIONS.find((f) => f.key === key);
    return flagDef?.defaultValue ?? defaultValue;
  }

  return data[key] ?? defaultValue;
}

import { Flag, CheckCircle2, Clock } from "lucide-react";
import { PageHeader } from "@/components/shared/PageHeader";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Skeleton } from "@/components/ui/skeleton";
import { format } from "date-fns";
import {
  FLAG_DEFINITIONS,
  useFeatureFlags,
  useUpdateFeatureFlag,
  type FlagDefinition,
} from "@/hooks/admin/use-feature-flags";
import { toast } from "sonner";

// ── Constants ─────────────────────────────────────────────────

const CATEGORY_LABELS: Record<FlagDefinition["category"], string> = {
  ui: "UI",
  feature: "Feature",
  system: "System",
};

const CATEGORY_BADGE_CLASSES: Record<FlagDefinition["category"], string> = {
  ui: "bg-sky-100 text-sky-700 border-0",
  feature: "bg-indigo-100 text-indigo-700 border-0",
  system: "bg-red-100 text-red-700 border-0",
};

// ── Skeleton ──────────────────────────────────────────────────

function FlagsSkeleton() {
  return (
    <div className="space-y-8">
      {Array.from({ length: 3 }).map((_, i) => (
        <Card key={i} className="border-border/50 shadow-soft">
          <CardHeader className="pb-3">
            <Skeleton className="h-5 w-32" />
          </CardHeader>
          <CardContent className="divide-y divide-slate-100">
            {Array.from({ length: 2 }).map((__, j) => (
              <div key={j} className="flex items-start gap-4 py-4">
                <Skeleton className="h-5 w-9 rounded-full mt-0.5" />
                <div className="flex-1 space-y-2">
                  <Skeleton className="h-4 w-40" />
                  <Skeleton className="h-3 w-72" />
                </div>
                <Skeleton className="h-5 w-8 rounded-full mt-0.5" />
              </div>
            ))}
          </CardContent>
        </Card>
      ))}
    </div>
  );
}

// ── Main page ─────────────────────────────────────────────────

export default function AdminFeatureFlags() {
  const flagsQuery = useFeatureFlags();
  const updateFlag = useUpdateFeatureFlag();

  const flags = flagsQuery.data?.flags ?? {};
  const updatedAt = flagsQuery.data?.updatedAt ?? null;

  const handleToggle = (flag: FlagDefinition, enabled: boolean) => {
    if (updateFlag.isPending) return;
    updateFlag.mutate(
      {
        key: flag.key,
        enabled,
        currentFlags: flags,
      },
      {
        onError: () => {
          // Optimistic revert is handled by React Query re-fetching on error
          toast.error(`Failed to toggle ${flag.label}. Please try again.`);
        },
      }
    );
  };

  const categories: FlagDefinition["category"][] = ["ui", "feature", "system"];

  return (
    <div className="space-y-8">
      <PageHeader
        title="Feature Flags"
        description="Toggle features on/off across the platform. Changes take effect immediately for all users."
      />

      {/* DB-backed success banner */}
      <div
        role="status"
        className="flex items-start gap-3 rounded-xl border border-green-200 bg-green-50 px-4 py-3.5"
      >
        <CheckCircle2 className="h-4 w-4 text-green-500 mt-0.5 shrink-0" />
        <div className="flex-1">
          <p className="text-sm font-medium text-green-800">
            Flags stored in database
          </p>
          <p className="text-xs text-green-700 mt-0.5">
            Feature flags are stored in{" "}
            <code className="font-mono text-xs bg-green-100 px-1 py-0.5 rounded">
              system_config
            </code>{" "}
            and apply platform-wide immediately.
            {updatedAt && (
              <span className="ml-1">
                Last updated{" "}
                {format(new Date(updatedAt), "MMM d, yyyy 'at' h:mm a")}.
              </span>
            )}
          </p>
        </div>
      </div>

      {/* Loading state */}
      {flagsQuery.isLoading ? (
        <FlagsSkeleton />
      ) : flagsQuery.isError ? (
        <div
          role="alert"
          className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700"
        >
          Failed to load feature flags. Check your admin permissions.
        </div>
      ) : (
        /* Flags by category */
        categories.map((category) => {
          const categoryFlags = FLAG_DEFINITIONS.filter(
            (f) => f.category === category
          );

          return (
            <Card key={category} className="border-border/50 shadow-soft">
              <CardHeader className="pb-3">
                <div className="flex items-center gap-2">
                  <Flag className="h-4 w-4 text-muted-foreground" />
                  <CardTitle className="text-base font-semibold capitalize">
                    {category === "ui"
                      ? "UI Visibility"
                      : category === "feature"
                      ? "Feature Toggles"
                      : "System Flags"}
                  </CardTitle>
                </div>
              </CardHeader>
              <CardContent className="divide-y divide-slate-100">
                {categoryFlags.map((flag) => {
                  const enabled = flags[flag.key] ?? flag.defaultValue;
                  const isPending = updateFlag.isPending && updateFlag.variables?.key === flag.key;

                  return (
                    <div
                      key={flag.key}
                      className="flex items-start gap-4 py-4 first:pt-0 last:pb-0"
                    >
                      {/* Toggle */}
                      <div className="pt-0.5">
                        <Switch
                          id={flag.key}
                          checked={enabled}
                          onCheckedChange={(v) => handleToggle(flag, v)}
                          disabled={isPending || updateFlag.isPending}
                          aria-label={`Toggle ${flag.label}`}
                        />
                      </div>

                      {/* Info */}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 flex-wrap">
                          <Label
                            htmlFor={flag.key}
                            className="text-sm font-medium cursor-pointer"
                          >
                            {flag.label}
                          </Label>
                          <Badge
                            className={`text-2xs px-1.5 py-0 ${
                              CATEGORY_BADGE_CLASSES[flag.category]
                            }`}
                          >
                            {CATEGORY_LABELS[flag.category]}
                          </Badge>
                          {flag.requiresSuperAdmin && (
                            <Badge className="bg-red-50 text-red-600 border-red-200 text-2xs px-1.5 py-0">
                              Super Admin
                            </Badge>
                          )}
                        </div>
                        <p className="mt-1 text-xs text-muted-foreground leading-relaxed">
                          {flag.description}
                        </p>
                        {updatedAt && (
                          <div className="mt-1.5 flex items-center gap-1 text-2xs text-muted-foreground/60">
                            <Clock className="h-2.5 w-2.5" />
                            <span>
                              Last changed{" "}
                              {format(
                                new Date(updatedAt),
                                "MMM d, yyyy 'at' h:mm a"
                              )}
                            </span>
                          </div>
                        )}
                      </div>

                      {/* Status pill */}
                      <div className="shrink-0 pt-0.5">
                        {isPending ? (
                          <Badge className="bg-muted/50 text-slate-500 border-0 text-xs animate-pulse">
                            Saving…
                          </Badge>
                        ) : (
                          <Badge
                            className={
                              enabled
                                ? "bg-green-100 text-green-700 border-0 text-xs"
                                : "bg-muted/50 text-slate-500 border-0 text-xs"
                            }
                          >
                            {enabled ? "On" : "Off"}
                          </Badge>
                        )}
