import { useLocation, Link } from "react-router-dom";
import { LayoutDashboard, ScanLine, FileText, Puzzle, Settings, Zap, Sparkles, ShieldCheck } from "lucide-react";
import { NavLink } from "@/components/NavLink";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarFooter,
  SidebarHeader,
  useSidebar,
} from "@/components/ui/sidebar";
import { Separator } from "@/components/ui/separator";
import { useAuth } from "@/contexts/AuthContext";
import { useFeatureFlag } from "@/hooks/use-feature-flag";
import { cn } from "@/lib/utils";

interface NavItem {
  title: string;
  url: string;
  icon: React.ElementType;
  flagKey?: string;
}

const BASE_NAV_ITEMS: NavItem[] = [
  { title: "Dashboard", url: "/dashboard", icon: LayoutDashboard },
  { title: "New Scan", url: "/scan", icon: ScanLine },
  { title: "AI Agents", url: "/agents", icon: Sparkles, flagKey: "agent_hub_enabled" },
  { title: "My Reports", url: "/reports", icon: FileText },
  { title: "Integrations", url: "/integrations", icon: Puzzle, flagKey: "integrations_enabled" },
  { title: "Settings", url: "/settings", icon: Settings },
];

export function AppSidebar() {
  const { state } = useSidebar();
  const collapsed = state === "collapsed";
  const location = useLocation();
  const { profile } = useAuth();

  const agentHubEnabled = useFeatureFlag("agent_hub_enabled", true);
  const integrationsEnabled = useFeatureFlag("integrations_enabled", true);

  const navItems = BASE_NAV_ITEMS.filter((item) => {
    if (item.flagKey === "agent_hub_enabled") return agentHubEnabled;
    if (item.flagKey === "integrations_enabled") return integrationsEnabled;
    return true;
  });

  const scansUsed = profile?.scans_used ?? 0;
  const scanLimit = profile?.scan_limit ?? 1;
  const usagePercent = Math.round((scansUsed / scanLimit) * 100);

  const isActive = (path: string) =>
    location.pathname === path || location.pathname.startsWith(path + "/");

  return (
    <Sidebar collapsible="icon" className="border-r-0">
      <SidebarHeader className="px-4 py-5">
        <Link to="/dashboard" className="flex items-center gap-2.5">
          <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-sidebar-primary shrink-0">
            <ScanLine className="h-3.5 w-3.5 text-white" />
          </div>
          {!collapsed && (
            <span className="text-base font-semibold tracking-tight text-white">
              ConvertScan
            </span>
          )}
        </Link>
      </SidebarHeader>

      <SidebarContent className="px-2">
        <SidebarGroup>
          <SidebarGroupContent>
            <SidebarMenu className="space-y-0.5">
              {navItems.map((item) => {
                const active = isActive(item.url);
                return (
                  <SidebarMenuItem key={item.title}>
                    <SidebarMenuButton
                      asChild
                      className={cn(
                        "h-9 transition-colors duration-150",
                        active
                          ? "bg-white/10 text-white"
                          : "text-sidebar-foreground hover:bg-white/5 hover:text-white/80"
                      )}
                    >
                      <NavLink to={item.url} activeClassName="">
                        <item.icon className={cn(
                          "h-4 w-4 shrink-0",
                          active ? "text-sidebar-primary" : ""
                        )} />
                        {!collapsed && <span className="text-sm">{item.title}</span>}
                      </NavLink>
                    </SidebarMenuButton>
                  </SidebarMenuItem>
                );
              })}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      </SidebarContent>

      <SidebarFooter className="p-3">
        {/* Admin panel shortcut */}
        {(profile?.role === "admin" || profile?.role === "super_admin") && (
          <Link
            to="/admin"
            className={cn(
              "flex items-center gap-2.5 rounded-md px-2.5 py-2 text-sm font-medium transition-colors mb-2",
              isActive("/admin")
                ? "bg-amber-500/15 text-amber-300"
                : "text-sidebar-foreground hover:bg-amber-500/10 hover:text-amber-300"
            )}
          >
            <ShieldCheck className="h-4 w-4 shrink-0" />
            {!collapsed && <span>Admin Panel</span>}
          </Link>
        )}

        {/* Scan usage indicator */}
        {!collapsed && (
          <div className="mb-3 rounded-lg bg-white/5 p-3">
            <div className="flex items-center justify-between mb-1.5">
              <span className="text-xs text-white/40">Scans used</span>
              <span className="text-xs font-medium text-white/70 tabular-nums">
                {profile ? `${scansUsed}/${scanLimit}` : "\u2014"}
              </span>
            </div>
            <Progress value={profile ? usagePercent : 0} className="h-1" />
            <div className="mt-1.5">
              <Badge
                variant="outline"
                className="border-white/10 bg-transparent text-2xs text-white/40 capitalize px-1.5 py-0"
              >
                {profile?.plan ?? "free"} plan
              </Badge>
            </div>
          </div>
        )}

        <Separator className="mb-3 bg-white/5" />

        {!collapsed ? (
          <Link
            to="/pricing"
            className="flex items-center justify-center gap-2 rounded-lg bg-sidebar-primary px-4 py-2 text-sm font-medium text-white transition-all hover:opacity-90 hover:shadow-lg hover:shadow-sidebar-primary/20"
          >
            <Zap className="h-3.5 w-3.5" />
            Upgrade Plan
          </Link>
        ) : (
          <Link
            to="/pricing"
            className="flex items-center justify-center rounded-lg bg-sidebar-primary p-2 text-white transition-opacity hover:opacity-90"
          >
            <Zap className="h-3.5 w-3.5" />
          </Link>
        )}
      </SidebarFooter>
    </Sidebar>
  );
}

