// ── Ban / unban user ──────────────────────────────────────────

interface ToggleBanArgs {
  userId: string;
  ban: boolean;
}

export function useToggleBan() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({ userId, ban }: ToggleBanArgs) => {
      if (!user) throw new Error("Not authenticated");

      const { error } = await supabase
        .from("profiles")
        .update({ is_banned: ban })
        .eq("id", userId);

      if (error) throw new Error(error.message);

      await writeAuditLog(user.id, ban ? "ban_user" : "unban_user", "profile", userId, {});
    },
    onSuccess: (_, { ban, userId }) => {
      toast.success(ban ? "User banned" : "User unbanned");
      queryClient.invalidateQueries({ queryKey: ["admin", "users"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "user", userId] });
      queryClient.invalidateQueries({ queryKey: ["admin", "stats"] });
    },
    onError: (error: Error) => {
      toast.error(`Failed to update ban status: ${error.message}`);
    },
  });
}

// ── Bulk change plan ──────────────────────────────────────────

interface BulkChangePlanArgs {
  userIds: string[];
  plan: PlanType;
}

export function useBulkChangePlan() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({ userIds, plan }: BulkChangePlanArgs) => {
      if (!user) throw new Error("Not authenticated");

      const newLimit = plan === "agency" ? 500 : plan === "pro" ? 25 : 3;

      await Promise.all(
        userIds.map((userId) =>
          supabase
            .from("profiles")
            .update({ plan, scan_limit: newLimit })
            .eq("id", userId)
            .then(({ error }) => {
              if (error) throw new Error(error.message);
            })
        )
      );

      await writeAuditLog(user.id, "bulk_change_plan", "profile", "bulk", {
        user_ids: userIds,
        new_plan: plan,
        count: userIds.length,
      });
    },
    onSuccess: (_, { userIds, plan }) => {
      toast.success(`Updated ${userIds.length} users to ${plan} plan`);
      queryClient.invalidateQueries({ queryKey: ["admin", "users"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "stats"] });
    },
    onError: (error: Error) => {
      toast.error(`Bulk plan change failed: ${error.message}`);
    },
  });
}

// ── Bulk reset scan count ─────────────────────────────────────

interface BulkResetScansArgs {
  userIds: string[];
}

export function useBulkResetScans() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({ userIds }: BulkResetScansArgs) => {
      if (!user) throw new Error("Not authenticated");

      await Promise.all(
        userIds.map((userId) =>
          supabase
            .from("profiles")
            .update({ scans_used: 0 })
            .eq("id", userId)
            .then(({ error }) => {
              if (error) throw new Error(error.message);
            })
        )
      );

      await writeAuditLog(user.id, "bulk_reset_scans", "profile", "bulk", {
        user_ids: userIds,
        count: userIds.length,
      });
    },
    onSuccess: (_, { userIds }) => {
      toast.success(`Reset scan count for ${userIds.length} users`);
      queryClient.invalidateQueries({ queryKey: ["admin", "users"] });
    },
    onError: (error: Error) => {
      toast.error(`Bulk reset failed: ${error.message}`);
    },
  });
}

