import { useState, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { useDebounce } from "@/hooks/use-debounce";
import {
  Search,
  Users as UsersIcon,
  ChevronUp,
  ChevronDown,
  ChevronsUpDown,
  ChevronLeft,
  ChevronRight,
  Download,
  Loader2,
  X,
} from "lucide-react";
import { PageHeader } from "@/components/shared/PageHeader";
import { EmptyState } from "@/components/shared/EmptyState";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { useAdminUsers, useExportUsers, type AdminUsersFilter } from "@/hooks/admin/use-admin-users";
import { useBulkChangePlan, useBulkResetScans } from "@/hooks/admin/use-admin-actions";
import type { ProfileRow } from "@/types/database";
import type { PlanType, UserRole } from "@/types/index";
import { format } from "date-fns";

const PLAN_BADGE_CLASSES: Record<PlanType, string> = {
  free: "bg-muted/50 text-foreground/80 border-0",
  pro: "bg-indigo-100 text-indigo-700 border-0",
  agency: "bg-purple-100 text-purple-700 border-0",
};

const ROLE_BADGE_CLASSES: Record<UserRole, string> = {
  user: "bg-muted/50 text-foreground/80 border-0",
  admin: "bg-amber-100 text-amber-700 border-0",
  super_admin: "bg-red-100 text-red-700 border-0",
};

type SortableColumn = "email" | "full_name" | "plan" | "scans_used" | "role" | "created_at";

function SortIcon({ column, sortColumn, sortAsc }: {
  column: SortableColumn;
  sortColumn: SortableColumn;
  sortAsc: boolean;
}) {
  if (sortColumn !== column) return <ChevronsUpDown className="ml-1 h-3.5 w-3.5 text-muted-foreground/40" />;
  return sortAsc
    ? <ChevronUp className="ml-1 h-3.5 w-3.5 text-primary" />
    : <ChevronDown className="ml-1 h-3.5 w-3.5 text-primary" />;
}

function TableSkeleton() {
  return (
    <>
      {Array.from({ length: 8 }).map((_, i) => (
        <TableRow key={i}>
          {Array.from({ length: 8 }).map((__, j) => (
            <TableCell key={j}>
              <Skeleton className="h-4 w-full max-w-[120px]" />
            </TableCell>
          ))}
        </TableRow>
      ))}
    </>
  );
}

const PAGE_SIZE = 20;

function SortableHeader({
  column,
  label,
  sortColumn,
  sortAsc,
  onSort,
}: {
  column: SortableColumn;
  label: string;
  sortColumn: SortableColumn;
  sortAsc: boolean;
  onSort: (col: SortableColumn) => void;
}) {
  return (
    <TableHead
      className="cursor-pointer select-none whitespace-nowrap"
      onClick={() => onSort(column)}
      aria-sort={
        sortColumn === column ? (sortAsc ? "ascending" : "descending") : "none"
      }
    >
      <span className="inline-flex items-center">
        {label}
        <SortIcon column={column} sortColumn={sortColumn} sortAsc={sortAsc} />
      </span>
    </TableHead>
  );
}

export default function AdminUsers() {
  const navigate = useNavigate();
  const [search, setSearch] = useState("");
  const [planFilter, setPlanFilter] = useState<PlanType | "">("");
  const [roleFilter, setRoleFilter] = useState<UserRole | "">("");
  const [page, setPage] = useState(0);
  const [sortColumn, setSortColumn] = useState<SortableColumn>("created_at");
  const [sortAsc, setSortAsc] = useState(false);

  // Bulk selection state
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [bulkPlan, setBulkPlan] = useState<PlanType | "">("");
  const [bulkPlanDialogOpen, setBulkPlanDialogOpen] = useState(false);
  const [pendingBulkPlan, setPendingBulkPlan] = useState<PlanType | null>(null);

  const debouncedSearch = useDebounce(search, 350);

  const filter: AdminUsersFilter = {
    search: debouncedSearch || undefined,
    plan: planFilter || undefined,
    role: roleFilter || undefined,
  };

  const { data, isLoading, isError } = useAdminUsers({
    page,
    pageSize: PAGE_SIZE,
    filter,
    sortColumn: sortColumn as keyof ProfileRow,
    sortAsc,
  });

  const exportUsersQuery = useExportUsers(filter);
  const [isExporting, setIsExporting] = useState(false);

  const bulkChangePlan = useBulkChangePlan();
  const bulkResetScans = useBulkResetScans();

  const totalPages = data ? Math.ceil(data.total / PAGE_SIZE) : 0;
  const visibleUsers = data?.users ?? [];
  const allVisibleSelected = visibleUsers.length > 0 && visibleUsers.every((u) => selectedIds.has(u.id));

  const handleSort = useCallback((col: SortableColumn) => {
    setSortColumn((prev) => {
      if (prev === col) {
        setSortAsc((asc) => !asc);
        return prev;
      }
      setSortAsc(true);
      return col;
    });
    setPage(0);
  }, []);

  const toggleSelect = useCallback((id: string) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, []);

  const toggleSelectAll = useCallback(() => {
    if (allVisibleSelected) {
      setSelectedIds((prev) => {
        const next = new Set(prev);
        visibleUsers.forEach((u) => next.delete(u.id));
        return next;
      });
    } else {
      setSelectedIds((prev) => {
        const next = new Set(prev);
        visibleUsers.forEach((u) => next.add(u.id));
        return next;
      });
    }
  }, [allVisibleSelected, visibleUsers]);

  const handleBulkPlanChange = (plan: PlanType | "") => {
    if (!plan) return;
    setBulkPlan(plan);
    setPendingBulkPlan(plan as PlanType);
    setBulkPlanDialogOpen(true);
  };

  const confirmBulkPlanChange = () => {
    if (!pendingBulkPlan) return;
    bulkChangePlan.mutate(
      { userIds: Array.from(selectedIds), plan: pendingBulkPlan },
      {
        onSuccess: () => {
          setSelectedIds(new Set());
          setBulkPlan("");
          setPendingBulkPlan(null);
          setBulkPlanDialogOpen(false);
        },
      }
    );
  };

  const handleBulkResetScans = () => {
    bulkResetScans.mutate(
      { userIds: Array.from(selectedIds) },
      {
        onSuccess: () => setSelectedIds(new Set()),
      }
    );
  };

  const handleExport = async () => {
    setIsExporting(true);
    try {
      const result = await exportUsersQuery.refetch();
      if (!result.data) return;
      const blob = new Blob([result.data], { type: "text/csv" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `users-${format(new Date(), "yyyy-MM-dd")}.csv`;
      a.click();
      URL.revokeObjectURL(url);
    } finally {
      setIsExporting(false);
    }
  };

  const selectedCount = selectedIds.size;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between gap-4">
        <PageHeader
          title="Users"
          description={
            data ? `${data.total.toLocaleString()} total users` : "All registered users"
          }
        />
        <Button
          variant="outline"
          size="sm"
          onClick={handleExport}
          disabled={isExporting}
          className="shrink-0"
        >
          {isExporting ? (
            <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />
          ) : (
            <Download className="mr-2 h-3.5 w-3.5" />
          )}
          {isExporting ? "Exporting…" : "Export CSV"}
        </Button>
      </div>

      {/* Filters */}
      <div className="flex flex-wrap items-center gap-3">
        <div className="relative flex-1 min-w-[200px] max-w-xs">
          <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            placeholder="Search by email or name..."
            value={search}
            onChange={(e) => { setSearch(e.target.value); setPage(0); }}
            className="pl-9"
            aria-label="Search users"
          />
        </div>

        <Select
          value={planFilter}
          onValueChange={(v) => {
            setPlanFilter(v as PlanType | "");
            setPage(0);
          }}
        >
          <SelectTrigger className="w-[130px]" aria-label="Filter by plan">
            <SelectValue placeholder="All plans" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="">All plans</SelectItem>
            <SelectItem value="free">Free</SelectItem>
            <SelectItem value="pro">Pro</SelectItem>
            <SelectItem value="agency">Agency</SelectItem>
          </SelectContent>
        </Select>

        <Select
          value={roleFilter}
          onValueChange={(v) => {
            setRoleFilter(v as UserRole | "");
            setPage(0);
          }}
        >
          <SelectTrigger className="w-[150px]" aria-label="Filter by role">
            <SelectValue placeholder="All roles" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="">All roles</SelectItem>
            <SelectItem value="user">User</SelectItem>
            <SelectItem value="admin">Admin</SelectItem>
            <SelectItem value="super_admin">Super Admin</SelectItem>
          </SelectContent>
        </Select>

        {(debouncedSearch || planFilter || roleFilter) && (
          <Button
            variant="ghost"
            size="sm"
            onClick={() => {
              setSearch("");
              setPlanFilter("");
              setRoleFilter("");
              setPage(0);
            }}
          >
            Clear filters
          </Button>
        )}
      </div>

      {/* Bulk action bar */}
      {selectedCount > 0 && (
        <div className="flex flex-wrap items-center gap-3 bg-indigo-50 border border-indigo-100 rounded-xl px-4 py-2.5">
          <span className="text-sm font-medium text-indigo-700">
            {selectedCount} {selectedCount === 1 ? "user" : "users"} selected
          </span>

          <div className="flex items-center gap-2 ml-auto flex-wrap">
            {/* Change plan dropdown */}
            <Select
              value={bulkPlan}
              onValueChange={(v) => handleBulkPlanChange(v as PlanType)}
            >
              <SelectTrigger className="w-[150px] h-8 text-xs border-indigo-200 bg-white">
                <SelectValue placeholder="Change plan…" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="free">Set to Free</SelectItem>
                <SelectItem value="pro">Set to Pro</SelectItem>
                <SelectItem value="agency">Set to Agency</SelectItem>
              </SelectContent>
            </Select>

            {/* Reset scan count */}
            <Button
              variant="outline"
              size="sm"
              className="h-8 text-xs border-indigo-200 text-indigo-700 hover:bg-indigo-100"
              onClick={handleBulkResetScans}
              disabled={bulkResetScans.isPending}
            >
              {bulkResetScans.isPending ? (
                <Loader2 className="mr-1.5 h-3 w-3 animate-spin" />
              ) : null}
              Reset Scan Count
            </Button>

            {/* Deselect all */}
            <Button
              variant="ghost"
              size="sm"
              className="h-8 text-xs text-indigo-600 hover:bg-indigo-100"
              onClick={() => setSelectedIds(new Set())}
            >
              <X className="mr-1 h-3 w-3" />
              Deselect All
            </Button>
          </div>
        </div>
      )}

      {/* Table */}
      <div className="rounded-xl border border-border/50 overflow-hidden overflow-x-auto scrollbar-thin">
        <Table>
          <TableHeader>
            <TableRow className="bg-muted/40 hover:bg-muted/40">
              {/* Select all checkbox */}
              <TableHead className="w-10">
                <Checkbox
                  checked={allVisibleSelected}
                  onCheckedChange={toggleSelectAll}
                  aria-label="Select all visible users"
                  disabled={isLoading || visibleUsers.length === 0}
                />
              </TableHead>
              <SortableHeader column="email" label="Email" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
              <SortableHeader column="full_name" label="Name" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
              <SortableHeader column="plan" label="Plan" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
              <SortableHeader column="scans_used" label="Scans Used" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
              <SortableHeader column="role" label="Role" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
              <SortableHeader column="created_at" label="Signed Up" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
              <TableHead className="w-10" />
            </TableRow>
          </TableHeader>
          <TableBody>
            {isLoading ? (
              <TableSkeleton />
            ) : isError ? (
              <TableRow>
                <TableCell
                  colSpan={8}
                  className="py-10 text-center text-sm text-red-600"
                >
                  Failed to load users. Check your admin permissions.
                </TableCell>
              </TableRow>
            ) : data?.users.length === 0 ? (
              <TableRow>
                <TableCell colSpan={8} className="p-0">
                  <EmptyState
                    icon={UsersIcon}
                    title="No users found"
                    description="Try adjusting your search or filters."
                  />
                </TableCell>
              </TableRow>
            ) : (
              data?.users.map((user) => {
                const isSelected = selectedIds.has(user.id);
                return (
                  <TableRow
                    key={user.id}
                    className={`hover:bg-muted/40 transition-colors ${isSelected ? "bg-indigo-50/50" : ""}`}
                  >
                    {/* Row checkbox */}
                    <TableCell
                      onClick={(e) => e.stopPropagation()}
                    >
                      <Checkbox
                        checked={isSelected}
                        onCheckedChange={() => toggleSelect(user.id)}
                        aria-label={`Select user ${user.email}`}
                      />
                    </TableCell>

                    {/* Rest of row — click to navigate */}
                    <TableCell
                      className="font-mono text-xs text-muted-foreground cursor-pointer"
                      onClick={() => navigate(`/admin/users/${user.id}`)}
                    >
                      {user.email}
                    </TableCell>
                    <TableCell
                      className="text-sm font-medium cursor-pointer"
                      onClick={() => navigate(`/admin/users/${user.id}`)}
                    >
                      <div className="flex items-center gap-1.5">
                        {user.full_name || (
                          <span className="text-muted-foreground/50">—</span>
                        )}
                        {user.is_banned && (
                          <Badge className="bg-red-100 text-red-700 border-0 text-2xs px-1.5 py-0">
                            Banned
                          </Badge>
                        )}
                      </div>
                    </TableCell>
                    <TableCell
                      className="cursor-pointer"
                      onClick={() => navigate(`/admin/users/${user.id}`)}
                    >
                      <Badge
                        className={`text-xs px-2 py-0.5 capitalize ${
                          PLAN_BADGE_CLASSES[user.plan]
                        }`}
                      >
                        {user.plan}
                      </Badge>
                    </TableCell>
                    <TableCell
                      className="text-sm text-muted-foreground cursor-pointer"
                      onClick={() => navigate(`/admin/users/${user.id}`)}
                    >
                      {user.scans_used} / {user.scan_limit}
                    </TableCell>
                    <TableCell
                      className="cursor-pointer"
                      onClick={() => navigate(`/admin/users/${user.id}`)}
                    >
                      <Badge
                        className={`text-xs px-2 py-0.5 capitalize ${
                          ROLE_BADGE_CLASSES[user.role]
                        }`}
                      >
                        {user.role.replace("_", " ")}
                      </Badge>
                    </TableCell>
                    <TableCell
                      className="text-sm text-muted-foreground cursor-pointer"
                      onClick={() => navigate(`/admin/users/${user.id}`)}
                    >
                      {format(new Date(user.created_at), "MMM d, yyyy")}
                    </TableCell>
                    <TableCell>
                      <ChevronRight className="h-4 w-4 text-muted-foreground/40" />
                    </TableCell>
                  </TableRow>
                );
              })
            )}
          </TableBody>
        </Table>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <p className="text-sm text-muted-foreground">
            Page {page + 1} of {totalPages} ({data?.total.toLocaleString()} users)
          </p>
          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => setPage((p) => Math.max(0, p - 1))}
              disabled={page === 0}
              aria-label="Previous page"
            >
              <ChevronLeft className="h-4 w-4" />
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={() => setPage((p) => Math.min(totalPages - 1, p + 1))}
              disabled={page >= totalPages - 1}
              aria-label="Next page"
            >
              <ChevronRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      )}

      {/* Bulk plan change confirmation dialog */}
      <AlertDialog open={bulkPlanDialogOpen} onOpenChange={setBulkPlanDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Change plan for {selectedCount} users?</AlertDialogTitle>
            <AlertDialogDescription>
              This will change the plan to{" "}
              <strong className="capitalize">{pendingBulkPlan}</strong> for all{" "}
              {selectedCount} selected users and update their scan limits
              accordingly. This affects their billing access.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={() => { setBulkPlan(""); setPendingBulkPlan(null); }}>
              Cancel
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={confirmBulkPlanChange}
              disabled={bulkChangePlan.isPending}
              className="bg-indigo-600 hover:bg-indigo-700"
            >
              {bulkChangePlan.isPending ? (
                <>
                  <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />
                  Updating…
                </>
              ) : (
                `Update ${selectedCount} Users`
              )}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

