  AreaChart,
  Area,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
} from "recharts";

// ── Skeleton helpers ──────────────────────────────────────────

function StatsSkeleton({ cols = 4 }: { cols?: number }) {
  return (
    <div className={`grid grid-cols-2 gap-4 lg:grid-cols-${cols}`}>
      {Array.from({ length: cols }).map((_, i) => (
        <Skeleton key={i} className="h-[120px] rounded-xl" />
      ))}
    </div>
  );
}

function AuditFeedSkeleton() {
  return (
    <div className="space-y-3">
      {Array.from({ length: 5 }).map((_, i) => (
        <div key={i} className="flex items-start gap-3">
          <Skeleton className="h-7 w-7 rounded-full shrink-0" />
          <div className="flex-1 space-y-1.5">
            <Skeleton className="h-4 w-48" />
            <Skeleton className="h-3 w-32" />
          </div>
        </div>
      ))}
    </div>
  );
}

function ChartSkeleton() {
  return <Skeleton className="h-[220px] w-full rounded-xl" />;
}

// ── Score color ───────────────────────────────────────────────

function getScoreColor(score: number): string {
  if (score >= 70) return "text-green-600";
  if (score >= 40) return "text-amber-600";
  return "text-red-600";
}

function getSuccessRateColor(rate: number): string {
  if (rate >= 85) return "text-green-600";
  if (rate >= 60) return "text-amber-600";
  return "text-red-600";
}

// ── Audit log constants ────────────────────────────────────────

const ACTION_LABELS: Record<string, string> = {
  change_plan: "Changed plan",
  change_role: "Changed role",
  reset_scan_count: "Reset scan count",
  ban_user: "Banned user",
  unban_user: "Unbanned user",
  bulk_change_plan: "Bulk plan change",
  bulk_reset_scans: "Bulk scan reset",
  retry_scan: "Retried scan",
  update_plan_limits: "Updated plan limits",
  update_pillar_weights: "Updated pillar weights",
};

const ACTION_COLORS: Record<string, string> = {
  change_plan: "bg-blue-100 text-blue-700",
  change_role: "bg-purple-100 text-purple-700",
  reset_scan_count: "bg-amber-100 text-amber-700",
  ban_user: "bg-red-100 text-red-700",
  unban_user: "bg-green-100 text-green-700",
  bulk_change_plan: "bg-indigo-100 text-indigo-700",
  bulk_reset_scans: "bg-amber-100 text-amber-700",
  retry_scan: "bg-sky-100 text-sky-700",
  update_plan_limits: "bg-teal-100 text-teal-700",
  update_pillar_weights: "bg-teal-100 text-teal-700",
};

// ── Main page ─────────────────────────────────────────────────

export default function AdminDashboard() {
  const stats = useAdminStats();
  const auditLog = useAuditLog({ page: 0, pageSize: 10 });
  const userGrowth = useUserGrowth();
  const scanVolume = useScanVolume();

  return (
    <div className="space-y-8">
      <PageHeader
        title="Admin Dashboard"
