            iconColor="text-green-600"
            iconBg="bg-green-100"
          />
          <KpiCard
            title="Failed Scans"
            value={stats.data?.failedScans ?? 0}
            icon={AlertTriangle}
            iconColor="text-red-600"
            iconBg="bg-red-100"
          />
        </div>
      )}

      {/* KPI row 2 — additional metrics */}
      {stats.isLoading ? (
        <StatsSkeleton cols={4} />
      ) : !stats.isError && (
        <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
          {/* Scan success rate */}
          <div className="rounded-xl border border-border/50 bg-card shadow-soft p-5 space-y-1">
            <div className="flex items-center justify-between">
              <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground">
                Scan Success Rate
              </p>
              <div className="rounded-lg bg-indigo-100 p-2">
                <Percent className="h-4 w-4 text-indigo-600" />
              </div>
            </div>
            <p className={`text-2xl font-bold tabular-nums ${getSuccessRateColor(stats.data?.scanSuccessRate ?? 0)}`}>
              {stats.data?.scanSuccessRate ?? 0}%
            </p>
          </div>

          {/* New users today */}
          <div className="rounded-xl border border-border/50 bg-card shadow-soft p-5 space-y-1">
            <div className="flex items-center justify-between">
              <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground">
                New Users Today
              </p>
              <div className="rounded-lg bg-green-100 p-2">
                <CalendarDays className="h-4 w-4 text-green-600" />
              </div>
            </div>
            <p className="text-2xl font-bold tabular-nums text-foreground">
              {stats.data?.newUsersToday ?? 0}
            </p>
          </div>

          {/* Avg score this month */}
          <div className="rounded-xl border border-border/50 bg-card shadow-soft p-5 space-y-1">
            <div className="flex items-center justify-between">
              <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground">
                Avg Score (Month)
              </p>
              <div className="rounded-lg bg-amber-100 p-2">
                <TrendingUp className="h-4 w-4 text-amber-600" />
              </div>
            </div>
            <p className={`text-2xl font-bold tabular-nums ${getScoreColor(stats.data?.avgScoreThisMonth ?? 0)}`}>
              {stats.data?.avgScoreThisMonth ?? 0}
              <span className="text-sm font-normal text-muted-foreground ml-1">/100</span>
            </p>
          </div>

          {/* Scans this month */}
          <div className="rounded-xl border border-border/50 bg-card shadow-soft p-5 space-y-1">
            <div className="flex items-center justify-between">
              <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground">
                Scans This Month
              </p>
              <div className="rounded-lg bg-sky-100 p-2">
                <BarChart2 className="h-4 w-4 text-sky-600" />
              </div>
            </div>
            <p className="text-2xl font-bold tabular-nums text-foreground">
              {stats.data?.scansThisMonth ?? 0}
            </p>
          </div>
        </div>
      )}

      {/* Charts row */}
      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
        {/* User Growth chart */}
        <Card className="border-border/50 shadow-soft">
          <CardHeader className="pb-3">
            <div className="flex items-center gap-2">
              <Users className="h-4 w-4 text-muted-foreground" />
              <CardTitle className="text-base font-semibold">
                User Growth (Last 30 Days)
              </CardTitle>
            </div>
          </CardHeader>
          <CardContent>
            {userGrowth.isLoading ? (
              <ChartSkeleton />
            ) : userGrowth.isError ? (
              <p className="text-sm text-muted-foreground py-8 text-center">
                Failed to load user growth data.
              </p>
            ) : (userGrowth.data?.length ?? 0) === 0 ? (
              <p className="text-sm text-muted-foreground py-8 text-center">
                No user signups in the last 30 days.
              </p>
            ) : (
              <ResponsiveContainer width="100%" height={220}>
                <AreaChart
                  data={userGrowth.data}
                  margin={{ top: 4, right: 4, left: -28, bottom: 0 }}
                >
                  <defs>
                    <linearGradient id="userGrowthGradient" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#6366f1" stopOpacity={0.2} />
                      <stop offset="95%" stopColor="#6366f1" stopOpacity={0} />
                    </linearGradient>
                  </defs>
