                  />
                  <Area
                    type="monotone"
                    dataKey="cumulative"
                    stroke="#6366f1"
                    strokeWidth={2}
                    fill="url(#userGrowthGradient)"
                    name="Total Users"
                  />
                  <Bar dataKey="count" fill="#818cf8" name="New Users" />
