          <CardHeader className="pb-3">
            <div className="flex items-center gap-2">
              <ScanLine className="h-4 w-4 text-muted-foreground" />
              <CardTitle className="text-base font-semibold">
                Scan Volume (Last 7 Days)
              </CardTitle>
            </div>
          </CardHeader>
          <CardContent>
            {scanVolume.isLoading ? (
              <ChartSkeleton />
            ) : scanVolume.isError ? (
              <p className="text-sm text-muted-foreground py-8 text-center">
                Failed to load scan volume data.
              </p>
            ) : (scanVolume.data?.every((d) => d.total === 0)) ? (
              <p className="text-sm text-muted-foreground py-8 text-center">
                No scans in the last 7 days.
              </p>
            ) : (
              <ResponsiveContainer width="100%" height={220}>
                <BarChart
                  data={scanVolume.data}
                  margin={{ top: 4, right: 4, left: -28, bottom: 0 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                  <XAxis
                    dataKey="day"
                    tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
                    tickLine={false}
                    axisLine={false}
                  />
                  <YAxis
                    tick={{ fontSize: 10, fill: "hsl(var(--muted-foreground))" }}
                    tickLine={false}
                    axisLine={false}
                    allowDecimals={false}
                  />
                  <Tooltip
                    contentStyle={{
                      background: "hsl(var(--card))",
                      border: "1px solid hsl(var(--border))",
                      borderRadius: "8px",
                      fontSize: "12px",
                    }}
                  />
                  <Legend
                    wrapperStyle={{ fontSize: "11px", paddingTop: "8px" }}
                  />
                  <Bar dataKey="completed" fill="#22c55e" name="Completed" radius={[3, 3, 0, 0]} />
                  <Bar dataKey="failed" fill="#ef4444" name="Failed" radius={[3, 3, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Recent audit activity */}
      <Card className="border-border/50 shadow-soft">
        <CardHeader className="pb-3">
          <div className="flex items-center gap-2">
            <ScrollText className="h-4 w-4 text-muted-foreground" />
            <CardTitle className="text-base font-semibold">Recent Admin Activity</CardTitle>
          </div>
        </CardHeader>
        <CardContent>
          {auditLog.isLoading ? (
            <AuditFeedSkeleton />
          ) : auditLog.isError ? (
            <p className="text-sm text-muted-foreground">
              No audit log entries yet.
            </p>
          ) : auditLog.data?.entries.length === 0 ? (
            <p className="py-8 text-center text-sm text-muted-foreground">
              No admin actions recorded yet.
            </p>
          ) : (
            <ul className="space-y-4" aria-label="Recent admin actions">
              {auditLog.data?.entries.map((entry) => (
                <li
                  key={entry.id}
                  className="flex items-start gap-3"
                >
                  <div className="mt-0.5 flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-muted/50">
                    <ScrollText className="h-3.5 w-3.5 text-slate-500" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="text-sm font-medium text-foreground">
                        {entry.admin_name ?? entry.admin_email ?? entry.admin_id}
                      </span>
                      <Badge
                        className={`text-2xs px-1.5 py-0 font-medium border-0 ${
                          ACTION_COLORS[entry.action] ?? "bg-muted/50 text-foreground/80"
                        }`}
                      >
                        {ACTION_LABELS[entry.action] ?? entry.action}
                      </Badge>
                    </div>
                    <div className="mt-0.5 flex items-center gap-1.5">
                      <Clock className="h-3 w-3 text-muted-foreground/60" />
                      <span className="text-xs text-muted-foreground">
                        {formatDistanceToNow(new Date(entry.created_at), {
                          addSuffix: true,
                        })}
                      </span>
                      {entry.target_id && entry.target_id !== "bulk" && entry.target_id !== "system" && (
                        <>
                          <span className="text-muted-foreground/40 text-xs">·</span>
                          <span className="font-mono text-xs text-muted-foreground/70">
                            {entry.target_id.slice(0, 8)}...
                          </span>
                        </>
                      )}
                    </div>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

/**
 * Admin support hooks.
 *
 * Run in Supabase SQL editor to create the support_requests table:
 *
 * CREATE TABLE IF NOT EXISTS support_requests (
 *   id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
 *   user_id UUID REFERENCES profiles(id) ON DELETE SET NULL,
 *   user_email TEXT NOT NULL,
 *   subject TEXT NOT NULL,
 *   message TEXT NOT NULL,
 *   status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'in_progress', 'resolved', 'closed')),
 *   priority TEXT NOT NULL DEFAULT 'normal' CHECK (priority IN ('low', 'normal', 'high', 'urgent')),
 *   admin_notes TEXT,
 *   created_at TIMESTAMPTZ DEFAULT NOW(),
 *   updated_at TIMESTAMPTZ DEFAULT NOW(),
 *   resolved_at TIMESTAMPTZ
 * );
 * ALTER TABLE support_requests ENABLE ROW LEVEL SECURITY;
 * CREATE POLICY "Users can insert own requests" ON support_requests
 *   FOR INSERT WITH CHECK (auth.uid() = user_id);
 * CREATE POLICY "Users can read own requests" ON support_requests
 *   FOR SELECT USING (auth.uid() = user_id);
 * CREATE POLICY "Admins can manage all" ON support_requests
 *   FOR ALL USING (
 *     EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role IN ('admin', 'super_admin'))
 *   );
 */

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import type { ProfileRow } from "@/types/database";
import { toast } from "sonner";

// ── Types ─────────────────────────────────────────────────────

export interface AtRiskUser extends ProfileRow {
  has_failed_scans: boolean;
  never_scanned: boolean;
  at_scan_limit: boolean;
  last_scan_date: string | null;
}

export interface SupportStats {
  usersAtLimit: number;
  usersWithFailedScans: number;
  newSignupsLastWeek: number;
}

export type SupportStatus = "open" | "in_progress" | "resolved" | "closed";
export type SupportPriority = "low" | "normal" | "high" | "urgent";

export interface SupportRequest {
  id: string;
  user_id: string | null;
  user_email: string;
  subject: string;
  message: string;
  status: SupportStatus;
  priority: SupportPriority;
  admin_notes: string | null;
  created_at: string;
  updated_at: string;
  resolved_at: string | null;
  // Joined from profiles
  user_name?: string | null;
}

// ── Fetch helpers ─────────────────────────────────────────────

async function fetchAtRiskUsers(): Promise<AtRiskUser[]> {
  const sevenDaysAgo = new Date(
    Date.now() - 7 * 24 * 60 * 60 * 1000
  ).toISOString();

  const { data: profiles, error: profilesError } = await supabase
    .from("profiles")
    .select("*")
    .order("created_at", { ascending: false })
    .limit(200);

  if (profilesError) throw new Error(profilesError.message);

  const { data: failedScansData, error: failedError } = await supabase
    .from("scans")
    .select("user_id")
    .eq("status", "failed")
    .gte("created_at", sevenDaysAgo);

  if (failedError) throw new Error(failedError.message);

  const { data: lastScans, error: lastScansError } = await supabase
    .from("scans")
    .select("user_id, created_at")
    .order("created_at", { ascending: false });

  if (lastScansError) throw new Error(lastScansError.message);

  const failedUserIds = new Set(
    (failedScansData ?? []).map((r) => r.user_id)
  );

  const lastScanMap = new Map<string, string>();
  for (const scan of lastScans ?? []) {
    if (!lastScanMap.has(scan.user_id)) {
      lastScanMap.set(scan.user_id, scan.created_at);
    }
  }

  const atRisk: AtRiskUser[] = [];

  for (const profile of profiles ?? []) {
    const p = profile as ProfileRow;
    const atLimit = p.scans_used >= p.scan_limit;
    const hasFailed = failedUserIds.has(p.id);
    const neverScanned = !lastScanMap.has(p.id);
    const lastScanDate = lastScanMap.get(p.id) ?? null;

    if (atLimit || hasFailed || neverScanned) {
      atRisk.push({
        ...p,
        has_failed_scans: hasFailed,
        never_scanned: neverScanned,
        at_scan_limit: atLimit,
        last_scan_date: lastScanDate,
      });
    }
  }

  return atRisk.sort((a, b) => {
    const scoreA = (a.at_scan_limit ? 3 : 0) + (a.has_failed_scans ? 2 : 0) + (a.never_scanned ? 1 : 0);
    const scoreB = (b.at_scan_limit ? 3 : 0) + (b.has_failed_scans ? 2 : 0) + (b.never_scanned ? 1 : 0);
    return scoreB - scoreA;
  });
}

async function fetchSupportStats(): Promise<SupportStats> {
  const sevenDaysAgo = new Date(
    Date.now() - 7 * 24 * 60 * 60 * 1000
  ).toISOString();

  const [
    { data: profiles, error: profilesError },
    { data: failedScans, error: failedError },
    { count: newSignups, error: signupsError },
  ] = await Promise.all([
    supabase.from("profiles").select("scans_used, scan_limit"),
    supabase
      .from("scans")
      .select("user_id")
      .eq("status", "failed")
      .gte("created_at", sevenDaysAgo),
    supabase
      .from("profiles")
      .select("*", { count: "exact", head: true })
      .gte("created_at", sevenDaysAgo),
  ]);

  if (profilesError) throw new Error(profilesError.message);
  if (failedError) throw new Error(failedError.message);
  if (signupsError) throw new Error(signupsError.message);

  const usersAtLimit = (profiles ?? []).filter(
    (p) => p.scans_used >= p.scan_limit
  ).length;

  const usersWithFailedScans = new Set(
    (failedScans ?? []).map((r) => r.user_id)
  ).size;

  return {
    usersAtLimit,
    usersWithFailedScans,
    newSignupsLastWeek: newSignups ?? 0,
  };
}

async function fetchSupportRequests(filter?: { status?: SupportStatus }): Promise<SupportRequest[]> {
  let query = supabase
    .from("support_requests")
    .select(`
      *,
      profiles:user_id (
        full_name
      )
    `)
    .order("created_at", { ascending: false });

  if (filter?.status) {
    query = query.eq("status", filter.status);
  }

  const { data, error } = await query;
  if (error) throw new Error(error.message);

  return (data ?? []).map((row) => {
    const profileData = row.profiles as { full_name: string | null } | null;
    return {
      id: row.id,
      user_id: row.user_id,
      user_email: row.user_email,
      subject: row.subject,
      message: row.message,
      status: row.status as SupportStatus,
      priority: row.priority as SupportPriority,
      admin_notes: row.admin_notes,
      created_at: row.created_at,
      updated_at: row.updated_at,
      resolved_at: row.resolved_at,
      user_name: profileData?.full_name ?? null,
    };
  });
}

// ── Hooks ─────────────────────────────────────────────────────

export function useAtRiskUsers() {
  return useQuery({
    queryKey: ["admin", "at-risk-users"],
    queryFn: fetchAtRiskUsers,
    staleTime: 60_000,
  });
}

export function useSupportStats() {
  return useQuery({
    queryKey: ["admin", "support-stats"],
    queryFn: fetchSupportStats,
    staleTime: 60_000,
  });
}

export function useSupportRequests(filter?: { status?: SupportStatus }) {
  return useQuery({
    queryKey: ["admin", "support-requests", filter],
    queryFn: () => fetchSupportRequests(filter),
    staleTime: 30_000,
  });
}

export function useUpdateSupportRequest() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({
      id,
      status,
      priority,
      admin_notes,
    }: {
      id: string;
      status?: SupportStatus;
      priority?: SupportPriority;
      admin_notes?: string;
    }) => {
      const updates: Record<string, unknown> = {
        updated_at: new Date().toISOString(),
      };
      if (status !== undefined) {
        updates.status = status;
        if (status === "resolved" || status === "closed") {
          updates.resolved_at = new Date().toISOString();
        }
      }
      if (priority !== undefined) updates.priority = priority;
      if (admin_notes !== undefined) updates.admin_notes = admin_notes;

      const { error } = await supabase
        .from("support_requests")
        .update(updates)
        .eq("id", id);

      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      toast.success("Support request updated");
      queryClient.invalidateQueries({ queryKey: ["admin", "support-requests"] });
    },
    onError: (error: Error) => {
      toast.error(`Failed to update request: ${error.message}`);
    },
  });
}

/**
