import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "sonner";
import type { SupportRequest, SupportPriority } from "@/hooks/admin/use-admin-support";

interface SubmitSupportRequestArgs {
  subject: string;
  message: string;
  priority: SupportPriority;
}

export function useSubmitSupportRequest() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({ subject, message, priority }: SubmitSupportRequestArgs) => {
      if (!user) throw new Error("You must be logged in to submit a support request.");

      const { error } = await supabase.from("support_requests").insert({
        user_id: user.id,
        user_email: user.email ?? "",
        subject,
        message,
        priority,
        status: "open",
      });

      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      toast.success("Support request submitted. We'll get back to you soon.");
      queryClient.invalidateQueries({ queryKey: ["support-requests", "my"] });
    },
    onError: (error: Error) => {
      toast.error(`Failed to submit request: ${error.message}`);
    },
  });
}

export function useMySuportRequests() {
  const { user } = useAuth();

  return useQuery({
    queryKey: ["support-requests", "my", user?.id],
    queryFn: async () => {
      if (!user) return [] as SupportRequest[];

      const { data, error } = await supabase
        .from("support_requests")
        .select("id, subject, status, priority, created_at")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false })
        .limit(10);

      if (error) throw new Error(error.message);
      return (data ?? []) as Pick<SupportRequest, "id" | "subject" | "status" | "priority" | "created_at">[];
    },
    enabled: !!user,
    staleTime: 60_000,
  });
}

