function SupportTicketsTable() {
  const [activeTab, setActiveTab] = useState<"all" | SupportStatus>("all");

  const statusFilter = activeTab === "all" ? undefined : { status: activeTab };
  const ticketsQuery = useSupportRequests(statusFilter);

  const tickets = ticketsQuery.data ?? [];

  const countsByStatus = {
    all: tickets.length,
    open: tickets.filter((t) => t.status === "open").length,
    in_progress: tickets.filter((t) => t.status === "in_progress").length,
    resolved: tickets.filter((t) => t.status === "resolved").length,
  };

  return (
    <div className="space-y-4">
      <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as typeof activeTab)}>
        <TabsList className="h-9">
          <TabsTrigger value="all" className="text-xs">All ({countsByStatus.all})</TabsTrigger>
          <TabsTrigger value="open" className="text-xs">Open ({countsByStatus.open})</TabsTrigger>
          <TabsTrigger value="in_progress" className="text-xs">In Progress ({countsByStatus.in_progress})</TabsTrigger>
          <TabsTrigger value="resolved" className="text-xs">Resolved ({countsByStatus.resolved})</TabsTrigger>
