    onSuccess: () => {
      toast.success("Scan deleted");
      queryClient.invalidateQueries({ queryKey: ["admin", "scans"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "scan-stats"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "stats"] });
    },
    onError: (error: Error) => {
      toast.error(`Failed to delete scan: ${error.message}`);
    },
  });
}

